-- Seed competency taxonomy from CSV (Competency Taxonomy(in).csv)
-- Populates competency_taxonomy_seed and syncs to company_capabilities_ref.

DELETE FROM public.competency_taxonomy_seed;


SELECT id, name, category, parent_id, is_active FROM public.competency_taxonomy_seed
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, parent_id = EXCLUDED.parent_id, is_active = EXCLUDED.is_active;

